import fs from 'fs/promises';
import path from 'path';
import { z } from 'zod';
import type { ProjectLibrary } from '../ProjectLibrary';
import type { StaticLibraryPreviews } from '../StaticLibraryPreviews';
import { ProjectScreenshotService } from '../ProjectScreenshotService';
import {
  ProfileVariantInputSchema,
  type ProfileVariantInput,
  type ProfileReferenceInput,
} from '../../types/design-profile';
import { PROFILE_IMAGE_BYTES } from './ProfileMedia';
import { errorMessage } from '../../utils/errorMessage';

interface VariantServices {
  library: ProjectLibrary;
  previews?: StaticLibraryPreviews;
}
export interface PinnedVariant {
  projectId: string;
  sessionId: string;
  variantId: string;
  title: string;
  hasStaticPreview: boolean;
}
const pinState = z.object({ pinned: z.array(z.string().max(500)).max(1000) });
const JPEG_PREFIX = 'data:image/jpeg;base64,';

export class ProfileVariants {
  private readonly screenshots = new ProjectScreenshotService();
  constructor(private readonly services: VariantServices) {}

  async pins(projectId?: string) {
    const { library } = this.services;
    const projects = projectId
      ? [library.registry.get(projectId)]
      : library.listProjects();
    const variants = new Map<string, PinnedVariant>();
    const issues: Array<{ projectId: string; message: string }> = [];
    for (const project of projects) {
      try {
        const history = await library.history(project.id);
        const entries = await library.listVariants(project.id);
        const byPin = new Map(
          entries.map((entry) => [
            `row:past:${entry.manifest.sessionId}:${entry.manifest.variantId}`,
            entry,
          ]),
        );
        const roots =
          project.storageKind === 'bundle'
            ? [project.projectPath]
            : library.registry.historyRoots(project.id);
        for (const root of roots) {
          const stored = await history.readVariantsUiState(root);
          if (!stored) continue;
          for (const pin of pinState.parse(JSON.parse(stored)).pinned) {
            const entry = byPin.get(pin);
            if (!entry) continue;
            const { manifest } = entry;
            variants.set(JSON.stringify([project.id, pin]), {
              projectId: project.id,
              sessionId: manifest.sessionId,
              variantId: manifest.variantId,
              title: manifest.label,
              hasStaticPreview: entry.hasStaticPreview,
            });
          }
        }
      } catch (error) {
        issues.push({
          projectId: project.id,
          message: errorMessage(error, 'Saved pins are unavailable'),
        });
      }
    }
    return { variants: [...variants.values()], issues };
  }

  async load(
    input: ProfileVariantInput,
    signal: AbortSignal,
  ): Promise<{ reference: ProfileReferenceInput; image: Buffer }> {
    const value = ProfileVariantInputSchema.parse(input);
    signal.throwIfAborted();
    const { library, previews } = this.services;
    const found = await library.variant(value);
    if (
      !found ||
      found.detail.manifest.status === 'removed' ||
      found.detail.manifest.status === 'cancelled'
    )
      throw new Error('The saved direction is unavailable');
    const manifest = found.detail.manifest;
    let image: Buffer;
    if (value.imageFile) {
      const stat = await fs.lstat(value.imageFile);
      if (
        !path.isAbsolute(value.imageFile) ||
        !stat.isFile() ||
        stat.size > PROFILE_IMAGE_BYTES
      )
        throw new Error(
          'Supply a bounded regular screenshot file with an absolute path',
        );
      image = await fs.readFile(value.imageFile);
    } else {
      if (!found.detail.hasStaticPreview || !previews)
        throw new Error(
          'This direction needs an explicit screenshot; supply imageFile from its rendered preview',
        );
      const captured = await this.screenshots.capture(
        await previews.url(value),
      );
      if (!captured.startsWith(JPEG_PREFIX))
        throw new Error('The saved direction capture is not a supported image');
      image = Buffer.from(captured.slice(JPEG_PREFIX.length), 'base64');
    }
    signal.throwIfAborted();
    if (!image.length || image.length > PROFILE_IMAGE_BYTES)
      throw new Error('Saved direction image exceeds the media budget');
    const current = await library.variant(value);
    if (
      !current ||
      JSON.stringify(current.detail.manifest) !== JSON.stringify(manifest)
    )
      throw new Error(
        'The saved direction changed during capture; save it again',
      );
    const identity = {
      projectId: value.projectId,
      sessionId: value.sessionId,
      variantId: value.variantId,
    };
    return {
      image,
      reference: {
        provider: 'variant',
        remoteId: JSON.stringify(identity),
        title: manifest.label,
        text: manifest.brief,
        media: [],
        note: value.note,
        variant: {
          ...identity,
          ...(manifest.tree ? { treeSha: manifest.tree.treeSha } : {}),
        },
      },
    };
  }

  async close(): Promise<void> {
    await this.screenshots.close();
  }
}
